package db

// PostgreSQL 方言适配（v0.20 公开化 / 批次 G / ADR-018 §2.1）。
//
// # 为什么在驱动层改写，而不是改每一处 SQL
//
// 业务 SQL 散在 db / sync / api / backup 几百处，全部用 SQLite 的 `?` 占位符。
// 逐处改写意味着一次巨大的、与语义无关的 diff，以及两套 SQL 长期并存的漂移风险。
// 这里改为注册一个包装 pgx 的 database/sql 驱动：
//
//   - 每条语句执行前把 `?` 改写为 `$1…$n`（跳过字符串字面量、引号标识符与注释）；
//   - DDL（CREATE/ALTER TABLE）里的 SQLite 类型映射为 PG 类型：
//     INTEGER→BIGINT（SQLite 的 INTEGER 本来就是 64 位）、BLOB→BYTEA、REAL→DOUBLE PRECISION、
//     `INTEGER PRIMARY KEY AUTOINCREMENT`→`BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`；
//   - 少量**登记在案**的 SQLite 专属语句（PRAGMA、sqlite_master、pragma_table_info、
//     sqlite_sequence、VACUUM）按下面的 pgRewrites 表翻译成 PG 的等价物；
//   - **表里没有登记的 SQLite 专属语句一律报错**，绝不原样发给 PG 碰运气——
//     「静默跑出不同的结果」比「当场失败」危险得多。
//
// 业务代码因此对方言无感；确实需要不同**行为**的地方（备份快照、擦除的文件级哨兵扫描）
// 通过 IsPostgres(*sql.DB) 显式分支，不靠改写。
//
// # 事务与锁语义
//
// 与 SQLite 现状一致：单连接池（MaxOpenConns=1），配合 Service 的互斥锁，所有写入串行。
// 先保证正确性；以后要做并发需要重新论证每一处「读-判断-写」都在事务里。
//
// # 排序规则
//
// SQLite 默认 BINARY（字节序）比较。PG 的 ORDER BY 依赖数据库 locale——en_US 之类的
// 自然语言排序会让路径顺序、分页边界与 SQLite 不同。因此 OpenPostgres 要求数据库的
// datcollate 为 C / POSIX（或 C.UTF-8），否则拒绝启动。

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"database/sql/driver"
	"encoding/hex"
	"errors"
	"fmt"
	"net/url"
	"os"
	"regexp"
	"strings"
	gosync "sync"
	"sync/atomic"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/stdlib"
)

// pgDriver 只用作类型标记：IsPostgres 通过 (*sql.DB).Driver() 识别方言。
type pgDriver struct{}

func (pgDriver) Open(string) (driver.Conn, error) {
	return nil, errors.New("litesync pg driver: use OpenPostgres")
}

type pgConnector struct {
	inner driver.Connector
}

func (c *pgConnector) Connect(ctx context.Context) (driver.Conn, error) {
	conn, err := c.inner.Connect(ctx)
	if err != nil {
		return nil, err
	}
	return &pgConn{c: conn}, nil
}

func (c *pgConnector) Driver() driver.Driver { return pgDriver{} }

// pgConn 包装 pgx stdlib 的连接，在每条语句进入 PG 之前改写它。
type pgConn struct{ c driver.Conn }

var (
	_ driver.Conn               = (*pgConn)(nil)
	_ driver.ConnBeginTx        = (*pgConn)(nil)
	_ driver.ConnPrepareContext = (*pgConn)(nil)
	_ driver.ExecerContext      = (*pgConn)(nil)
	_ driver.QueryerContext     = (*pgConn)(nil)
	_ driver.Pinger             = (*pgConn)(nil)
	_ driver.NamedValueChecker  = (*pgConn)(nil)
	_ driver.SessionResetter    = (*pgConn)(nil)
	_ driver.Validator          = (*pgConn)(nil)
)

func (p *pgConn) Prepare(q string) (driver.Stmt, error) {
	return p.PrepareContext(context.Background(), q)
}

func (p *pgConn) PrepareContext(ctx context.Context, q string) (driver.Stmt, error) {
	q2, err := RewriteForPostgres(q)
	if err != nil {
		return nil, err
	}
	return p.c.(driver.ConnPrepareContext).PrepareContext(ctx, q2)
}

func (p *pgConn) Close() error { return p.c.Close() }

//nolint:staticcheck // driver.Conn 接口要求
func (p *pgConn) Begin() (driver.Tx, error) {
	return p.BeginTx(context.Background(), driver.TxOptions{})
}

func (p *pgConn) BeginTx(ctx context.Context, opts driver.TxOptions) (driver.Tx, error) {
	return p.c.(driver.ConnBeginTx).BeginTx(ctx, opts)
}

func (p *pgConn) ExecContext(ctx context.Context, q string, args []driver.NamedValue) (driver.Result, error) {
	q2, err := RewriteForPostgres(q)
	if err != nil {
		return nil, err
	}
	return p.c.(driver.ExecerContext).ExecContext(ctx, q2, args)
}

func (p *pgConn) QueryContext(ctx context.Context, q string, args []driver.NamedValue) (driver.Rows, error) {
	q2, err := RewriteForPostgres(q)
	if err != nil {
		return nil, err
	}
	return p.c.(driver.QueryerContext).QueryContext(ctx, q2, args)
}

func (p *pgConn) Ping(ctx context.Context) error { return p.c.(driver.Pinger).Ping(ctx) }

func (p *pgConn) CheckNamedValue(nv *driver.NamedValue) error {
	// SQLite 接受 Go bool 写进 INTEGER 列（存 0/1）；PG 的 bigint 不接受 bool。
	// 业务代码里的布尔参数一律按 SQLite 的存储形式落成 0/1，两种库的数据完全一致。
	if b, ok := nv.Value.(bool); ok {
		if b {
			nv.Value = int64(1)
		} else {
			nv.Value = int64(0)
		}
		return nil
	}
	return p.c.(driver.NamedValueChecker).CheckNamedValue(nv)
}

func (p *pgConn) ResetSession(ctx context.Context) error {
	return p.c.(driver.SessionResetter).ResetSession(ctx)
}

func (p *pgConn) IsValid() bool {
	if v, ok := p.c.(driver.Validator); ok {
		return v.IsValid()
	}
	return true
}

// IsPostgres 报告这个连接池是不是 PostgreSQL（需要不同**行为**的地方显式分支用）。
func IsPostgres(d *sql.DB) bool {
	if d == nil {
		return false
	}
	_, ok := d.Driver().(pgDriver)
	return ok
}

// IsUniqueViolation 判断唯一约束冲突（两种库的错误形态不同，业务代码只认这一个入口）。
func IsUniqueViolation(err error) bool {
	if err == nil {
		return false
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.Code == "23505"
	}
	return strings.Contains(err.Error(), "UNIQUE constraint failed")
}

// ---------------------------------------------------------------- 打开

// OpenPostgres 连接 PostgreSQL 并初始化 schema（与 SQLite 的 Open 走同一套 schema 与迁移）。
// dsn 只从环境变量来，不进日志。
func OpenPostgres(dsn string) (*sql.DB, error) {
	d, err := OpenPostgresRaw(dsn)
	if err != nil {
		return nil, err
	}
	if err := initSchema(d); err != nil {
		d.Close()
		return nil, err
	}
	return d, nil
}

// OpenPostgresRaw 只建立连接并检查排序规则（不建表、不写种子行）：
// 迁移/恢复的目标库、测试建 schema 用。
func OpenPostgresRaw(dsn string) (*sql.DB, error) {
	cfg, err := pgx.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse postgres dsn: %w", redactDSNErr(err))
	}
	// DescribeExec：每条语句先 Describe 拿到参数类型再编码——与 SQLite 的动态类型最兼容，
	// 也不缓存预编译语句（schema 升级后的 ALTER TABLE 不会让旧缓存失效报错）
	cfg.DefaultQueryExecMode = pgx.QueryExecModeDescribeExec
	d := sql.OpenDB(&pgConnector{inner: stdlib.GetConnector(*cfg)})
	d.SetMaxOpenConns(1)
	d.SetMaxIdleConns(1)
	d.SetConnMaxLifetime(0)
	d.SetConnMaxIdleTime(0)
	if err := d.Ping(); err != nil {
		d.Close()
		return nil, fmt.Errorf("connect postgres: %w", redactDSNErr(err))
	}
	var collate string
	if err := d.QueryRow(`SELECT datcollate FROM pg_database WHERE datname = current_database()`).Scan(&collate); err != nil {
		d.Close()
		return nil, fmt.Errorf("read database collation: %w", err)
	}
	if !byteOrderCollation(collate) {
		d.Close()
		return nil, fmt.Errorf("postgres database collation is %q; LiteSync requires C/POSIX (byte-order, same as SQLite): "+
			"create it with `CREATE DATABASE ... LC_COLLATE 'C' LC_CTYPE 'C' TEMPLATE template0`", collate)
	}
	return d, nil
}

func byteOrderCollation(c string) bool {
	switch strings.ToUpper(c) {
	case "C", "POSIX", "C.UTF-8", "C.UTF8":
		return true
	}
	return false
}

// redactDSNErr 去掉错误信息里可能带出的口令。
func redactDSNErr(err error) error {
	msg := err.Error()
	re := regexp.MustCompile(`(password=)[^\s&]+|(://[^:/@]+:)[^@]+@`)
	return errors.New(re.ReplaceAllString(msg, "${1}${2}***@"))
}

// ---------------------------------------------------------------- 测试支持

var (
	testPGMu      gosync.Mutex
	testPGSchemas = map[string]bool{}
)

// testPostgresDSN：设置了 LITESYNC_TEST_PG_DSN 时，Open(path) 改用 PG（测试在两种库上
// 各跑一遍的开关）。每个文件路径映射到一个独立 schema——同一路径重开得到同一份数据
// （测试里「关闭再打开」模拟重启的语义保持不变），不同测试互不干扰。
func testPostgresDSN() string { return os.Getenv("LITESYNC_TEST_PG_DSN") }

func openTestPostgres(base, path string) (*sql.DB, error) {
	sum := sha256.Sum256([]byte(path))
	schema := "t_" + hex.EncodeToString(sum[:10])
	testPGMu.Lock()
	if !testPGSchemas[schema] {
		admin, err := OpenPostgresRaw(base)
		if err != nil {
			testPGMu.Unlock()
			return nil, err
		}
		_, err = admin.Exec(`CREATE SCHEMA IF NOT EXISTS ` + schema)
		admin.Close()
		if err != nil {
			testPGMu.Unlock()
			return nil, fmt.Errorf("create test schema: %w", err)
		}
		testPGSchemas[schema] = true
	}
	testPGMu.Unlock()
	return OpenPostgres(WithSearchPath(base, schema))
}

// WithSearchPath 把 search_path 写进 DSN（每条新连接都会带上，不怕连接池重连）。
// 一个 PG 库里用独立 schema 放 LiteSync 时也用它（测试的隔离 schema、恢复演练的目标）。
func WithSearchPath(dsn, schema string) string {
	if strings.HasPrefix(dsn, "postgres://") || strings.HasPrefix(dsn, "postgresql://") {
		u, err := url.Parse(dsn)
		if err == nil {
			q := u.Query()
			q.Set("search_path", schema)
			u.RawQuery = q.Encode()
			return u.String()
		}
	}
	return dsn + " search_path=" + schema
}

// ---------------------------------------------------------------- 改写

type pgRewrite struct {
	match   *regexp.Regexp
	replace string // 整条语句替换为它（已是 PG 语法、已用 $n 占位）
	// template：replace 是正则模板（$1 引用捕获组；PG 占位符写作 $$1）
	template bool
}

// pgRewrites：登记在案的 SQLite 专属语句 → PG 等价物。匹配作用于去掉首尾空白的整条语句。
var pgRewrites = []pgRewrite{
	// 表是否存在（迁移分支判断）
	{regexp.MustCompile(`(?is)^SELECT COUNT\(\*\) FROM sqlite_master WHERE type = 'table' AND name = \?$`),
		`SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = current_schema() AND table_type = 'BASE TABLE' AND table_name = $1`, false},
	// 列清单（缺列则补）
	{regexp.MustCompile(`(?is)^SELECT name FROM pragma_table_info\(\?\)$`),
		`SELECT column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = $1`, false},
	{regexp.MustCompile(`(?is)^SELECT name FROM pragma_table_info\('([A-Za-z0-9_]+)'\)$`),
		`SELECT column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = '$1'`, true},
	// migration_journal 的 CHECK 扩容只属于升级上来的旧 SQLite 库；PG 的表总是按最新 DDL 建立，
	// 返回一段「已含 'blob'」的说明文本让迁移判定为无事可做
	{regexp.MustCompile(`(?is)^SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'migration_journal'$`),
		`SELECT 'kind IN (''object'',''tombstone'',''version'',''blob'')' FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'migration_journal'`, false},
	// v5 升级路径的 AUTOINCREMENT 历史最大值：PG 库从不经过 v5，没有这张表
	{regexp.MustCompile(`(?is)^SELECT seq FROM sqlite_sequence WHERE name = 'changes'$`),
		`SELECT 0::bigint WHERE false`, false},
	// 空闲页统计：PG 由 autovacuum 回收，不触发低频 VACUUM
	{regexp.MustCompile(`(?is)^PRAGMA freelist_count$`), `SELECT 0::bigint`, false},
	{regexp.MustCompile(`(?is)^PRAGMA page_count$`), `SELECT 1::bigint`, false},
	// 数据库文件清单（擦除的文件级哨兵扫描用）：PG 的数据文件不在应用可读的位置，返回空集，
	// 调用方据此跳过文件扫描并如实报告（见 sync/erasure.go）
	{regexp.MustCompile(`(?is)^PRAGMA database_list$`), `SELECT 0::bigint, ''::text, ''::text WHERE false`, false},
	// WAL / 连接级开关：PG 无对应物，空操作
	{regexp.MustCompile(`(?is)^PRAGMA (journal_mode|synchronous|busy_timeout|foreign_keys|secure_delete|wal_checkpoint)\b.*$`), `SELECT 1`, false},
	// 擦除后的整库重建：PG 的 VACUUM FULL 重写全部表文件，死元组随之消失
	{regexp.MustCompile(`(?is)^VACUUM$`), `VACUUM FULL`, false},
}

var sqliteOnly = regexp.MustCompile(`(?i)\bPRAGMA\b|\bsqlite_master\b|\bsqlite_sequence\b|\bpragma_[a-z_]+\b|\bVACUUM\s+INTO\b|\bstrftime\s*\(`)

var (
	reDDL      = regexp.MustCompile(`(?i)\b(CREATE\s+TABLE|ALTER\s+TABLE)\b`)
	reAutoinc  = regexp.MustCompile(`(?i)\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b`)
	reInteger  = regexp.MustCompile(`(?i)\bINTEGER\b`)
	reBlob     = regexp.MustCompile(`(?i)\bBLOB\b`)
	reReal     = regexp.MustCompile(`(?i)\bREAL\b`)
	pgRewriteC = gosync.Map{} // 原语句 → 改写结果（热路径缓存）
	// pgRewriteN 限制缓存条数：业务 SQL 是有限集合，但按列表长度拼接的 IN (?, …) 与
	// 按表名拼接的语句会产生多种文本——超过上限后只改写不缓存，内存不随运行时间增长
	pgRewriteN atomic.Int64
)

const pgRewriteCacheMax = 4096

// RewriteForPostgres 把一条（或多条，DDL 批量执行时）SQLite 方言的语句改写为 PG 方言。
func RewriteForPostgres(q string) (string, error) {
	if v, ok := pgRewriteC.Load(q); ok {
		return v.(string), nil
	}
	out, err := rewriteForPostgres(q)
	if err != nil {
		return "", err
	}
	if pgRewriteN.Add(1) <= pgRewriteCacheMax {
		pgRewriteC.Store(q, out)
	}
	return out, nil
}

func rewriteForPostgres(q string) (string, error) {
	trimmed := strings.TrimSpace(q)
	for _, r := range pgRewrites {
		if r.match.MatchString(trimmed) {
			if r.template {
				return r.match.ReplaceAllString(trimmed, r.replace), nil
			}
			return r.replace, nil
		}
	}
	if m := sqliteOnly.FindString(stripLiteralsAndComments(q)); m != "" {
		head := trimmed
		if len(head) > 80 {
			head = head[:80]
		}
		return "", fmt.Errorf("SQLite-specific statement has no registered PostgreSQL translation (%q in %q)", m, head)
	}
	if reDDL.MatchString(q) {
		q = mapOutsideLiterals(q, func(code string) string {
			code = reAutoinc.ReplaceAllString(code, "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
			code = reInteger.ReplaceAllString(code, "BIGINT")
			code = reBlob.ReplaceAllString(code, "BYTEA")
			return reReal.ReplaceAllString(code, "DOUBLE PRECISION")
		})
	}
	return rewritePlaceholders(q), nil
}

// rewritePlaceholders 把字面量与注释之外的 `?` 依次改写为 $1…$n。
func rewritePlaceholders(q string) string {
	if !strings.Contains(q, "?") {
		return q
	}
	var b strings.Builder
	b.Grow(len(q) + 8)
	n := 0
	scanSQL(q, func(seg string, code bool) {
		if !code {
			b.WriteString(seg)
			return
		}
		for i := 0; i < len(seg); i++ {
			if seg[i] == '?' {
				n++
				fmt.Fprintf(&b, "$%d", n)
				continue
			}
			b.WriteByte(seg[i])
		}
	})
	return b.String()
}

// mapOutsideLiterals 只对字面量与注释之外的代码片段应用 f。
func mapOutsideLiterals(q string, f func(string) string) string {
	var b strings.Builder
	scanSQL(q, func(seg string, code bool) {
		if code {
			b.WriteString(f(seg))
		} else {
			b.WriteString(seg)
		}
	})
	return b.String()
}

func stripLiteralsAndComments(q string) string {
	var b strings.Builder
	scanSQL(q, func(seg string, code bool) {
		if code {
			b.WriteString(seg)
		} else {
			b.WriteByte(' ')
		}
	})
	return b.String()
}

// scanSQL 把 SQL 切成「代码」与「非代码」（'字符串'、"标识符"、-- 注释、/* 注释 */）片段。
func scanSQL(q string, emit func(seg string, code bool)) {
	start := 0
	i := 0
	flush := func(end int, code bool) {
		if end > start {
			emit(q[start:end], code)
		}
		start = end
	}
	for i < len(q) {
		c := q[i]
		switch {
		case c == '\'' || c == '"':
			flush(i, true)
			j := i + 1
			for j < len(q) {
				if q[j] == c {
					if j+1 < len(q) && q[j+1] == c { // '' / "" 转义
						j += 2
						continue
					}
					j++
					break
				}
				j++
			}
			i = j
			flush(i, false)
		case c == '-' && i+1 < len(q) && q[i+1] == '-':
			flush(i, true)
			j := strings.IndexByte(q[i:], '\n')
			if j < 0 {
				i = len(q)
			} else {
				i += j
			}
			flush(i, false)
		case c == '/' && i+1 < len(q) && q[i+1] == '*':
			flush(i, true)
			j := strings.Index(q[i+2:], "*/")
			if j < 0 {
				i = len(q)
			} else {
				i += j + 4
			}
			flush(i, false)
		default:
			i++
		}
	}
	flush(len(q), true)
}
